package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity@Table(name="spms_rating_source_item",uniqueConstraints=@UniqueConstraint(name="uk_spms_rating_source_item",columnNames={"agency_id","rating_case_id","commitment_item_id"}))
public class PerformanceRatingSourceItem extends RspAuditedEntity{@Column(name="rating_case_id",nullable=false,length=36)private String ratingCaseId;@Column(name="commitment_item_id",nullable=false,length=36)private String commitmentItemId;@Column(name="commitment_section_id",nullable=false,length=36)private String commitmentSectionId;@Column(name="indicator_version_id",nullable=false,length=36)private String indicatorVersionId;@Column(name="monitoring_update_id",nullable=false,length=36)private String monitoringUpdateId;@Column(name="item_label",nullable=false,length=200)private String itemLabel;@Column(name="section_code",nullable=false,length=80)private String sectionCode;@Column(name="section_weight",nullable=false,precision=7,scale=4)private BigDecimal sectionWeight;@Column(name="item_weight",nullable=false,precision=7,scale=4)private BigDecimal itemWeight;@Column(name="reporting_date",nullable=false)private LocalDate reportingDate;@Column(name="accomplishment_narrative",nullable=false,length=4000)private String accomplishmentNarrative;@Column(name="accomplished_value",precision=19,scale=6)private BigDecimal accomplishedValue;@Column(name="evidence_fingerprint",nullable=false,length=64)private String evidenceFingerprint;@Column(name="display_order",nullable=false)private int displayOrder;protected PerformanceRatingSourceItem(){}public PerformanceRatingSourceItem(String a,String c,PerformanceCommitmentItem i,PerformanceCommitmentSection s,PerformanceMonitoringUpdate u,String evidence){super(a);ratingCaseId=c;commitmentItemId=i.getId();commitmentSectionId=s.getId();indicatorVersionId=i.getIndicatorVersionId();monitoringUpdateId=u.getId();itemLabel=i.getLabel();sectionCode=s.getSectionCode();sectionWeight=s.getWeightPercent();itemWeight=i.getWeightPercent();reportingDate=u.getReportingDate();accomplishmentNarrative=u.getNarrativeAccomplishment();accomplishedValue=u.getAccomplishedValue();evidenceFingerprint=requiredText(evidence,"evidenceFingerprint");displayOrder=i.getDisplayOrder();}public String getRatingCaseId(){return ratingCaseId;}public String getCommitmentItemId(){return commitmentItemId;}public String getCommitmentSectionId(){return commitmentSectionId;}public String getIndicatorVersionId(){return indicatorVersionId;}public String getMonitoringUpdateId(){return monitoringUpdateId;}public String getItemLabel(){return itemLabel;}public String getSectionCode(){return sectionCode;}public BigDecimal getSectionWeight(){return sectionWeight;}public BigDecimal getItemWeight(){return itemWeight;}public LocalDate getReportingDate(){return reportingDate;}public String getAccomplishmentNarrative(){return accomplishmentNarrative;}public BigDecimal getAccomplishedValue(){return accomplishedValue;}public String getEvidenceFingerprint(){return evidenceFingerprint;}public int getDisplayOrder(){return displayOrder;}}
